#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // Split: [0..x-1] [x..n-y-1] [n-y..n-1]
    // Result: [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2; placed++){
        // Find where (placed+1) is
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element at pos to position (n-1)
        if(pos != n-1) {
            // We want p[pos] to end up at end
            // Use x = pos+1, y = n-1-pos
            // But need x+y < n: (pos+1)+(n-1-pos) = n, not < n
            // So use x = pos, y = n-1-pos (if pos > 0)
            // After op: suffix[n-(n-1-pos)..n-1] = [pos+1..n-1] goes to front
            // middle[pos..pos] stays in middle  
            // prefix[0..pos-1] goes to end
            // Result: [pos+1..n-1] [pos] [0..pos-1]
            // Element at pos goes to position (n-1-pos)
            if(pos > 0 && (n-1-pos) > 0 && pos + (n-1-pos) < n) {
                ops.push_back({pos, n-1-pos});
                apply_op(p, pos, n-1-pos);
                // Find new position
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
            // If still not at n-1, try x=1, y=n-1-pos
            if(pos != n-1 && pos > 0) {
                int x = pos+1, y = 1;
                if(x > 0 && y > 0 && x+y < n) {
                    ops.push_back({x, y});
                    apply_op(p, x, y);
                    for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                }
            }
        }
        if(pos == placed) continue;
        if(pos == n-1) {
            // Step 2: Move from n-1 to position placed
            // x = placed, y = 1: suffix=[n-1], middle=[placed..n-2], prefix=[0..placed-1]
            // Result: [p[n-1]] [p[placed]..p[n-2]] [p[0]..p[placed-1]]
            // Element goes to position 0... we want it at position placed
            // Try x = placed, y = 1 if placed > 0
            if(placed > 0 && placed + 1 < n) {
                ops.push_back({placed, 1});
                apply_op(p, placed, 1);
            } else if(placed == 0 && n > 2) {
                ops.push_back({1, 1});
                apply_op(p, 1, 1);
                // now element should be at position 0? No...
                // x=1,y=1: [p[n-1]][p[1]..p[n-2]][p[0]] -> element at n-1 goes to pos 0
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
